import RNA, random, sys, time

t = open('/tmp/t380.txt').read().strip()
N = len(t)
assert N == 380

# pair map
pm = [-1]*N
st = []
for i,c in enumerate(t):
    if c=='(': st.append(i)
    elif c==')':
        j=st.pop(); pm[i]=j; pm[j]=i

PAIRS = [('A','U'),('U','A'),('G','C'),('C','G'),('G','U'),('U','G')]

def allowed_at(i, seq):
    # if i is paired, must be complementary; else anything
    j = pm[i]
    if j < 0:
        return list('ACGU')
    # return bases that can pair with a partner (partner will be chosen consistently)
    return list('ACGU')

def random_seq():
    s = ['A']*N
    # assign by pairs
    for i in range(N):
        if pm[i] >= 0 and i < pm[i]:
            a = random.choice(['G','C','A','U'])
            comp = {'A':'U','U':'A','G':'C','C':'G'}
            # allow GU wobble too sometimes
            if random.random()<0.1:
                comp = {'A':'U','U':'A','G':'U','C':'G'}[a] if a in {'A','U'} else {'G':'C','C':'G'}[a]
            s[i]=a; s[pm[i]]=comp
        elif pm[i]<0:
            s[i]=random.choice('ACGU')
    return ''.join(s)

def fold(seq):
    fc=RNA.fold_compound(seq)
    mfe,s=fc.mfe()
    return s

def score_struct(s, target=t):
    # number of mismatched positions in pair set
    # build pair set for s
    pst=set(); mism=0
    st2=[]
    for i,c in enumerate(s):
        if c=='(':st2.append(i)
        elif c==')':
            j=st2.pop(); pst.add((j,i))
    tst=set()
    st3=[]
    for i,c in enumerate(target):
        if c=='(':st3.append(i)
        elif c==')':
            j=st3.pop(); tst.add((j,i))
    # symmetric diff of pair sets weighted
    missing = len(tst - pst)
    spurious = len(pst - tst)
    return missing*2 + spurious*1

def hamming_struct(s, target=t):
    return sum(1 for a,b in zip(s,target) if a!=b)

def sa(seed, iters, T0=2.0, Tend=0.05, time_limit=150):
    seq = list(seed)
    cur_struct = fold(''.join(seq))
    cur_score = score_struct(cur_struct)
    best_seq = seq[:]; best_score = cur_score
    start = time.time()
    comp = {'A':'U','U':'A','G':'C','C':'G'}
    for it in range(iters):
        if time.time()-start > time_limit:
            break
        T = T0 * (Tend/T0)**(it/iters) if iters>0 else T0
        # pick a paired position i to mutate (and its partner)
        i = random.randint(0, N-1)
        j = pm[i]
        old = seq[i]
        # choose new base
        if j>=0:
            # mutate pair together
            newpair = random.choice([('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')])
            ni,nj = newpair
            if seq[i]==ni and seq[j]==nj: continue
            oldj=seq[j]
            seq[i]=ni; seq[j]=nj
            new_struct = fold(''.join(seq))
            new_score = score_struct(new_struct)
            d = new_score - cur_score
            if d<=0 or random.random() < pow(2.718281828, -d/max(T,1e-6)):
                cur_struct=new_struct; cur_score=new_score
                if cur_score < best_score:
                    best_score=cur_score; best_seq=seq[:]
                    if best_score==0:
                        return ''.join(best_seq), 0
            else:
                seq[i]=old; seq[j]=oldj
        else:
            choices=[b for b in 'ACGU' if b!=old]
            ni=random.choice(choices)
            seq[i]=ni
            new_struct = fold(''.join(seq))
            new_score = score_struct(new_struct)
            d = new_score - cur_score
            if d<=0 or random.random() < pow(2.718281828, -d/max(T,1e-6)):
                cur_struct=new_struct; cur_score=new_score
                if cur_score < best_score:
                    best_score=cur_score; best_seq=seq[:]
                    if best_score==0:
                        return ''.join(best_seq), 0
            else:
                seq[i]=old
    return ''.join(best_seq), best_score

