t = open('/tmp/t380.txt').read().strip()
N = len(t)
assert N == 380

pm = [-1]*N
st = []
for i,c in enumerate(t):
    if c=='(': st.append(i)
    elif c==')':
        j=st.pop(); pm[i]=j; pm[j]=i

comp = {'A':'U','U':'A','G':'C','C':'G'}

def fold(seq):
    fc=RNA.fold_compound(seq)
    return fc.mfe()[0]

def pairs_of(s):
    P=set(); st2=[]
    for i,c in enumerate(s):
        if c=='(':st2.append(i)
        elif c==')':
            j=st2.pop(); P.add((j,i))
    return P

TP = pairs_of(t)

def score_struct(s):
    P = pairs_of(s)
    missing = len(TP - P)
    spurious = len(P - TP)
    return missing*3 + spurious*1

def random_seq():
    s=['A']*N
    for i in range(N):
        if pm[i]>=0 and i<pm[i]:
            a=random.choice(['G','C','A','U'])
            s[i]=a; s[pm[i]]=comp[a]
        elif pm[i]<0:
            s[i]=random.choice('ACGU')
    return ''.join(s)

def gc_seed():
    # GC-pair-dominant seed for stability
    s=['A']*N
    for i in range(N):
        if pm[i]>=0 and i<pm[i]:
            a=random.choice(['G','C','C','G','G','C'])  # bias GC
            s[i]=a; s[pm[i]]=comp[a]
        elif pm[i]<0:
            s[i]=random.choice(['A','U','A','U'])  # loops AU-ish
    return ''.join(s)

def sa(seed, iters, T0=3.0, Tend=0.02, time_limit=120):
    seq=list(seed)
    cur=fold(''.join(seq)); cur_s=score_struct(cur)
    best=seq[:]; best_s=cur_s; best_st=cur
    start=time.time()
    for it in range(iters):
        if time.time()-start>time_limit: break
        T=T0*(Tend/T0)**(it/iters) if iters>0 else T0
        i=random.randint(0,N-1); j=pm[i]; old=seq[i]
        if j>=0:
            np=random.choice([('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G'),('G','C'),('C','G')])
            ni,nj=np
            if seq[i]==ni and seq[j]==nj: continue
            oldj=seq[j]; seq[i]=ni; seq[j]=nj
            ns=fold(''.join(seq)); nsc=score_struct(ns)
            d=nsc-cur_s
            if d<=0 or random.random()<math.exp(-d/max(T,1e-6)):
                cur=ns; cur_s=nsc
                if cur_s<best_s:
                    best_s=cur_s; best=seq[:]; best_st=ns
                    if best_s==0: return ''.join(best),0,best_st
            else:
                seq[i]=old; seq[j]=oldj
        else:
            ch=[b for b in 'ACGU' if b!=old]
            ni=random.choice(ch); seq[i]=ni
            ns=fold(''.join(seq)); nsc=score_struct(ns)
            d=nsc-cur_s
            if d<=0 or random.random()<math.exp(-d/max(T,1e-6)):
                cur=ns; cur_s=nsc
                if cur_s<best_s:
                    best_s=cur_s; best=seq[:]; best_st=ns
                    if best_s==0: return ''.join(best),0,best_st
            else:
                seq[i]=old
    return ''.join(best),best_s,best_st

