nrestarts=int(sys.argv[1]) if len(sys.argv)>1 else 3
for r in range(nrestarts):
    seed = gc_seed() if r%2==0 else random_seq()
    s,sc,st = sa(seed, 20000, time_limit=120//max(nrestarts,1))
